import {key} from './core.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const topicLabel=t=>!t||t==='Do klasyfikacji'?'Bez przypisanego tematu':t;
const plural=n=>n===1?'powtórka':(n%10>=2&&n%10<=4&&(n%100<10||n%100>=20))?'powtórki':'powtórek';
const paths={cards:'M7 3h13v16H7zM3 7v14h13',check:'m3 6 2 2 4-4M12 6h9M3 13h6m3 0h9M3 20h6m3 0h9',chart:'M4 3v18h17M8 16v-4m5 4V8m5 8V5',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',calendar:'M5 5h14a2 2 0 0 1 2 2v13H3V7a2 2 0 0 1 2-2ZM7 2v6m10-6v6M3 11h18',clock:'M12 8v5l3 2M9 2h6M12 2v3',note:'M5 3h14v18H5zM8 8h8m-8 4h8m-8 4h5',arrow:'M5 12h14m-6-6 6 6-6 6',book:'M3 4h7l2 2 2-2h7v16h-7l-2 1-2-1H3zM12 6v15'};
export const icon=name=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.grid}"/>${name==='clock'?'<circle cx="12" cy="14" r="8"/>':''}</svg>`;
let selected='new',monthOffset=0,selectedDate='',currentData;
const dateKey=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const read=(k,f)=>{try{return JSON.parse(localStorage.getItem(k))??f}catch{return f}};
let timer=read('infectio-timer',{remaining:1500,end:null});if(!Number.isFinite(timer.remaining)||timer.remaining<0)timer={remaining:1500,end:null};
function remaining(){return timer.end?Math.max(0,Math.ceil((timer.end-Date.now())/1000)):timer.remaining}
function persistTimer(){try{localStorage.setItem('infectio-timer',JSON.stringify(timer))}catch{}}
function formatTime(s){return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`}
setInterval(()=>{const left=remaining();if(timer.end&&left===0){timer={remaining:0,end:null};persistTimer();const msg=document.querySelector('#timer-status');if(msg)msg.textContent='Sesja zakończona. Czas na przerwę.'}const out=document.querySelector('#timer-time');if(out)out.textContent=formatTime(left);const btn=document.querySelector('#timer-toggle');if(btn){btn.textContent=timer.end?'Ⅱ':'▶';btn.setAttribute('aria-label',timer.end?'Wstrzymaj timer':'Uruchom timer')}},1000);
function pools(db,p){return{new:db.filter(i=>i.question&&i.answer&&i.kind!=='DO_POPRAWY'&&!p[key(i)]?.seen),review:db.filter(i=>i.kind!=='DO_POPRAWY'&&p[key(i)]?.due<=Date.now()),known:db.filter(i=>p[key(i)]?.seen&&p[key(i)]?.lastResult===true),all:db}}
function taskCards(db,p){const pool=pools(db,p)[selected];return pool.length?pool.slice(0,selected==='new'?1:3).map((i,n)=>`<article class="task-card"><div class="task-tags"><span class="task-tag lavender">${esc({FISZKA:'Fiszka',ABCDE:'Pytanie testowe',ODPOWIEDZ_OTWARTA:'Pytanie otwarte'}[i.kind]||'Archiwum')}</span><button class="task-open" data-detail="${esc(key(i))}" aria-label="Szczegóły pytania ${esc(i.id)}: odpowiedź i źródło">Odpowiedź i źródło</button></div><p class="task-topic">${esc(topicLabel(i.topic))}</p><h2 class="task-question">${esc(i.question||'Rekord niekompletny')}</h2><div class="task-source"><span class="source-avatar">${i.kind==='ABCDE'?'Q':'F'}</span><span>${esc(i.id)}<small>${/AUTHOR_EBM/.test(i.provenance||'')?'Pytanie autorskie EBM':'Materiał z biblioteki'}</small></span></div><div class="task-footer"><span>${p[key(i)]?.seen?'✓ Już ćwiczone':'Jeszcze nie ćwiczone'}</span><button data-learn="${esc(key(i))}">${icon('book')}Ucz się</button><button data-plan="${esc(key(i))}">${icon('calendar')}Zaplanuj</button></div></article>`).join(''):`<div class="board-empty"><span>${icon('book')}</span><h2>${selected==='review'?'Brak zaległych powtórek':selected==='known'?'Tu pojawią się zapamiętane pytania':'Ta kolejka jest pusta'}</h2><p>Wybierz tryb nauki i zrób kolejny krok.</p><button class="primary" data-start="FISZKA">Otwórz fiszki</button></div>`}
function calendar(db,p){const now=new Date(),month=new Date(now.getFullYear(),now.getMonth()+monthOffset,1),total=new Date(month.getFullYear(),month.getMonth()+1,0).getDate(),offset=(month.getDay()+6)%7;const due={};for(const i of db){const d=p[key(i)]?.due;if(d){const k=dateKey(new Date(d));due[k]=(due[k]||0)+1}}
const cells=Array.from({length:offset},()=>'<span class="day-blank" aria-hidden="true"></span>').join('')+Array.from({length:total},(_,j)=>{const date=new Date(month.getFullYear(),month.getMonth(),j+1),k=dateKey(date),today=k===dateKey(now);return `<button class="calendar-day ${today?'today':''} ${due[k]?'due-day':''} ${selectedDate===k?'chosen':''}" data-day="${k}" aria-label="${j+1} ${month.toLocaleDateString('pl-PL',{month:'long',year:'numeric'})}${today?', dziś':''}, ${due[k]||0} powtórek" aria-pressed="${selectedDate===k}">${j+1}${due[k]?'<i></i>':''}</button>`}).join('');
return `<div class="widget-head"><h2>${icon('calendar')} Kalendarz</h2><div class="month-controls"><button data-month="-1" aria-label="Poprzedni miesiąc">‹</button><span>${month.toLocaleDateString('pl-PL',{month:'short',year:'numeric'})}</span><button data-month="1" aria-label="Następny miesiąc">›</button></div></div><div class="weekdays">${['Pn','Wt','Śr','Cz','Pt','So','Nd'].map(x=>`<span>${x}</span>`).join('')}</div><div class="calendar-grid">${cells}</div><div class="calendar-caption">${selectedDate?`${esc(selectedDate)} · ${due[selectedDate]||0} zaplanowanych powtórek`:'Wybierz dzień, aby zobaczyć liczbę powtórek.'}</div><button class="calendar-plan" data-plan="" data-plan-date="${selectedDate}">${icon('calendar')}Zaplanuj powtórkę</button><a class="plan-link" href="#progress">Zobacz plan powtórek</a><span class="calendar-legend">● Dziś <i>●</i> Zaplanowane powtórki</span>`}
const modes=[['FISZKA','Fiszki','cards','Odkryj odpowiedź po własnej próbie'],['ODPOWIEDZ_OTWARTA','Pytania otwarte','note','Odpowiedz po swojemu, potem sprawdź i oceń się'],['ABCDE','Quiz ABCDE','check','Wybierz odpowiedź i od razu zobacz wynik']];
function sessionTiles(db){const c=db.reduce((m,i)=>(m[i.kind]=(m[i.kind]||0)+1,m),{});return modes.filter(([k])=>c[k]).map(([k,t,ic,d])=>`<button class="session-tile" data-start="${k}">${icon(ic)}<span><b>${t}</b><small>${d}</small></span><em>${c[k]||0}</em></button>`).join('')}
function dashboard(db,p,s){
 const pool=pools(db,p),notes=read('infectio-notes',''),last=Object.values(p).reduce((n,x)=>Math.max(n,x.last||0),0),due=s.due.length;
 // one primary action: repeat what is due, otherwise start learning
 const rs=read('infectio-session',null),resume=rs&&Array.isArray(rs.keys)&&rs.keys.length&&rs.index<rs.keys.length?`<button class="primary" data-resume>${icon('book')}Wznów naukę (${rs.index+1} / ${rs.keys.length})</button>`:'';let cta=due?`<button class="primary" data-start="review">${icon('book')}Rozpocznij powtórki (${due})</button>`:`<button class="primary" data-start="${['FISZKA','ODPOWIEDZ_OTWARTA','ABCDE'].find(k=>db.some(i=>i.kind===k))||'ABCDE'}">${icon('book')}Zacznij naukę</button>`;if(resume)cta=resume+cta.replace('class="primary"','class=""');
 return `<div class="dash-title-row"><div><h1>Twój rytm nauki</h1><p class="dash-sub">${due?`Na dziś: ${due} ${plural(due)}`:'Brak zaległych powtórek'} · ${pool.new.length} do nauki</p></div><span class="dash-updated"><i></i>${last?'Ostatnia nauka: '+new Date(last).toLocaleDateString('pl-PL'):'Gotowe na Twoją pierwszą sesję'}</span></div><div class="dashboard-actions">${cta}<button data-plan="">${icon('calendar')}Zaplanuj powtórkę</button></div>
<div class="dashboard-grid"><div class="dash-main">

<section class="session-widget widget"><div class="widget-head"><h2>${icon('book')} Twoja sesja</h2><span class="small-label">Wybierz tryb · własne tempo</span></div><div class="session-options">${sessionTiles(db)}</div></section>
<div class="dash-tools"><section class="timer-widget widget"><div class="widget-head"><h2>${icon('clock')} Timer</h2><button id="timer-reset" aria-label="Zresetuj timer do 25 minut">↺</button></div><div class="timer-controls"><output id="timer-time">${formatTime(remaining())}</output><button id="timer-toggle" aria-label="${timer.end?'Wstrzymaj timer':'Uruchom timer'}">${timer.end?'Ⅱ':'▶'}</button></div><span id="timer-status" role="status">25 minut skupienia</span></section>
<section class="notes-widget widget"><div class="widget-head"><h2>${icon('note')} Notatki</h2></div><label class="sr-only" for="quick-notes">Twoja notatka do nauki</label><textarea id="quick-notes" placeholder="Co chcesz dziś powtórzyć?">${esc(notes)}</textarea><span id="notes-status" role="status">Zapis lokalny</span></section></div>
</div><div class="dash-side">
<section class="progress-widget widget"><div class="widget-head"><h2>${icon('grid')} Mój postęp</h2><a href="#progress" aria-label="Szczegóły postępu">↗</a></div><div class="progress-message"><small>TWOJA BIBLIOTEKA</small><strong>${s.done}<span> / ${db.length}</span></strong><p>przerobionych pozycji</p><div class="progress"><span style="width:${Math.min(100,s.done/db.length*100)}%"></span></div></div><div class="progress-bubbles"><div><span>Trafność quizów</span><strong>${s.accuracy}</strong></div><div><span>Powtórki na teraz</span><strong>${due}</strong></div></div><div class="progress-footer"><span>Wyniki wyłącznie z Twojej nauki</span><a href="#progress" aria-label="Otwórz postęp">${icon('arrow')}</a></div></section>
<section class="calendar-widget widget" id="calendar-widget">${calendar(db,p)}</section>
</div></div><div class="dash-disclaimer">${db.length} pozycji z pakietu v4. Pełne archiwum 392 rekordów nie zostało dostarczone. Materiały edukacyjne; źródła i statusy znajdziesz w bibliotece.</div>`}
export function renderDashboard(db,p,s){currentData={db,p,s};return dashboard(db,p,s)}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.board&&currentData){selected=b.dataset.board;document.querySelectorAll('[data-board]').forEach(x=>{x.classList.toggle('selected',x.dataset.board===selected);x.setAttribute('aria-pressed',String(x.dataset.board===selected))});document.querySelector('#task-grid').innerHTML=taskCards(currentData.db,currentData.p)}if(b.dataset.month||b.dataset.day){if(b.dataset.month){monthOffset+=Number(b.dataset.month);selectedDate=''}else selectedDate=b.dataset.day;document.querySelector('#calendar-widget').innerHTML=calendar(currentData.db,currentData.p)}if(b.id==='timer-toggle'){if(timer.end){timer.remaining=remaining();timer.end=null}else{timer.remaining=remaining()||1500;timer.end=Date.now()+timer.remaining*1000}persistTimer();b.textContent=timer.end?'Ⅱ':'▶';b.setAttribute('aria-label',timer.end?'Wstrzymaj timer':'Uruchom timer');document.querySelector('#timer-status').textContent=timer.end?'Sesja w toku': 'Sesja wstrzymana'}if(b.id==='timer-reset'){timer={remaining:1500,end:null};persistTimer();document.querySelector('#timer-time').textContent='25:00';document.querySelector('#timer-toggle').textContent='▶';document.querySelector('#timer-toggle').setAttribute('aria-label','Uruchom timer');document.querySelector('#timer-status').textContent='25 minut skupienia'}});
document.addEventListener('input',e=>{if(e.target.id==='quick-notes'){try{localStorage.setItem('infectio-notes',JSON.stringify(e.target.value));document.querySelector('#notes-status').textContent='Zapisano na tym urządzeniu'}catch{document.querySelector('#notes-status').textContent='Nie udało się zapisać notatki'}}});
